package com.bankedclues;

import java.util.HashMap;
import java.util.Map;
import java.util.Objects;

/** Client-session cache, separated by RuneScape save profile. No disk persistence. */
final class BankClueTracker
{
	private final Map<String, Snapshot> profiles = new HashMap<>();
	private String profile;
	private Snapshot current;

	void selectProfile(String key)
	{
		if (Objects.equals(key, profile))
		{
			return;
		}
		markStale();
		profile = key;
		current = key == null ? null : profiles.computeIfAbsent(key, ignored -> new Snapshot());
		if (current != null)
		{
			current.inventory = null;
		}
	}

	void refreshBank(ClueCounts counts, Map<Integer, Long> inventory)
	{
		if (current != null && counts != null)
		{
			current.counts = counts;
			current.stale = false;
			current.inventory = inventory == null ? null : new HashMap<>(inventory);
		}
	}

	void observeInventory(Map<Integer, Long> inventory)
	{
		if (current == null || inventory == null)
		{
			return;
		}
		if (current.inventory != null && !current.inventory.equals(inventory))
		{
			markStale();
		}
		current.inventory = new HashMap<>(inventory);
	}

	void markStale()
	{
		if (current != null && current.counts != null)
		{
			current.stale = true;
		}
	}

	void suspend()
	{
		selectProfile(null);
	}

	void clear()
	{
		profiles.clear();
		profile = null;
		current = null;
	}

	ClueCounts getCounts()
	{
		return current == null ? null : current.counts;
	}

	boolean isStale()
	{
		return current != null && current.stale;
	}

	private static final class Snapshot
	{
		private ClueCounts counts;
		private boolean stale;
		private Map<Integer, Long> inventory;
	}
}

package com.bankedclues;

import java.awt.BorderLayout;
import java.awt.Font;
import java.awt.GridLayout;
import java.util.EnumMap;
import java.util.Map;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.QuantityFormatter;

final class BankedCluesPanel extends PluginPanel
{
	private final JLabel status = new JLabel();
	private final JLabel scrollTotal = new JLabel();
	private final JLabel casketTotal = new JLabel();
	private final JComboBox<String> tierFilter = new JComboBox<>();
	private final Map<ClueItemType, ClueItemTile> tiles = new EnumMap<>(ClueItemType.class);
	private ClueCounts counts;

	BankedCluesPanel(ItemManager itemManager)
	{
		setLayout(new BorderLayout(0, 12));
		JPanel heading = new JPanel();
		heading.setLayout(new BoxLayout(heading, BoxLayout.Y_AXIS));
		heading.setOpaque(false);
		JLabel title = new JLabel("Banked Clues");
		title.setForeground(ColorScheme.BRAND_ORANGE);
		title.setFont(title.getFont().deriveFont(Font.BOLD, 16f));
		title.setAlignmentX(LEFT_ALIGNMENT);
		heading.add(title);
		heading.add(Box.createVerticalStrut(10));

		JPanel totals = new JPanel(new GridLayout(1, 2, 6, 0));
		totals.setOpaque(false);
		totals.setAlignmentX(LEFT_ALIGNMENT);
		totals.add(scrollTotal);
		totals.add(casketTotal);
		heading.add(totals);
		heading.add(Box.createVerticalStrut(12));

		JLabel filterLabel = new JLabel("Clue tier");
		filterLabel.setAlignmentX(LEFT_ALIGNMENT);
		heading.add(filterLabel);
		heading.add(Box.createVerticalStrut(4));
		tierFilter.addItem("All");
		for (ClueTier tier : ClueTier.values())
		{
			tierFilter.addItem(tier.getDisplayName());
		}
		tierFilter.setAlignmentX(LEFT_ALIGNMENT);
		tierFilter.setToolTipText("Filter cached bank counts by clue tier");
		tierFilter.getAccessibleContext().setAccessibleName("Clue tier");
		heading.add(tierFilter);
		heading.add(Box.createVerticalStrut(10));
		status.setAlignmentX(LEFT_ALIGNMENT);
		heading.add(status);
		add(heading, BorderLayout.NORTH);

		JPanel grid = new JPanel(new GridLayout(3, 2, 8, 8));
		grid.setOpaque(false);
		for (ClueItemType type : ClueItemType.values())
		{
			ClueItemTile tile = new ClueItemTile(type, itemManager);
			tiles.put(type, tile);
			grid.add(tile);
		}
		add(grid, BorderLayout.CENTER);
		tierFilter.addActionListener(event -> refreshItems());
		showCounts(null, false, false);
	}

	// Called exclusively on the Swing event dispatch thread.
	void showCounts(ClueCounts counts, boolean stale, boolean bankOpen)
	{
		this.counts = counts;
		String message = counts == null
			? "Visit a bank to load your clues."
			: stale ? "Counts may be outdated.<br>Visit a bank to refresh."
			: bankOpen ? "Bank counts up to date." : "Showing your last bank snapshot.";
		status.setText("<html><body style='width:180px'>" + message + "</body></html>");
		status.setForeground(stale ? ColorScheme.BRAND_ORANGE : ColorScheme.LIGHT_GRAY_COLOR);
		refreshItems();
	}

	private void refreshItems()
	{
		int selected = tierFilter.getSelectedIndex();
		ClueTier tier = selected <= 0 ? null : ClueTier.values()[selected - 1];
		scrollTotal.setText("Scrolls: " + (counts == null ? "\u2014" : QuantityFormatter.quantityToStackSize(counts.getScrollTotal(tier))));
		casketTotal.setText("Caskets: " + (counts == null ? "\u2014" : QuantityFormatter.quantityToStackSize(counts.getTotal(ClueItemType.CASKET, tier))));
		scrollTotal.setToolTipText("Loose clues plus geodes, bottles, nests and boxes"
			+ (counts == null ? "." : ": " + counts.getScrollTotal(tier)));
		casketTotal.setToolTipText("Completed Treasure Trail reward caskets"
			+ (counts == null ? "." : ": " + counts.getTotal(ClueItemType.CASKET, tier)));
		for (ClueItemType type : ClueItemType.values())
		{
			tiles.get(type).showCount(tier, counts == null ? null : counts.getTotal(type, tier));
		}
	}
}

package com.bankedclues;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.Map;
import java.util.Objects;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ProfileChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

@Slf4j
@PluginDescriptor(
	name = "Banked Clues",
	description = "Remembers banked clues, clue sources and reward caskets by tier",
	tags = {"bank", "clue", "scroll", "casket", "treasure", "trails"}
)
public class BankedCluesPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ItemManager itemManager;

	private volatile boolean active;
	private volatile UiSession uiSession;
	private boolean refreshQueued;
	private int generation;
	private boolean bankUpdatePending;
	private boolean bankChangedAway;
	private final BankClueTracker tracker = new BankClueTracker();

	@Override
	protected void startUp()
	{
		UiSession session = new UiSession();
		uiSession = session;
		active = true;
		SwingUtilities.invokeLater(() ->
		{
			if (session.stopped)
			{
				return;
			}
			session.panel = new BankedCluesPanel(itemManager);
			session.button = NavigationButton.builder()
				.tooltip("Banked Clues")
				.icon(createIcon())
				.priority(7)
				.panel(session.panel)
				.build();
			clientToolbar.addNavigation(session.button);
		});
		clientThread.invokeLater(() ->
		{
			if (uiSession == session && !session.stopped)
			{
				tracker.clear();
				invalidatePending();
				queueRefresh();
			}
		});
		log.debug("BankedClues started!");
	}

	@Override
	protected void shutDown()
	{
		active = false;
		UiSession session = uiSession;
		uiSession = null;
		if (session != null)
		{
			session.stopped = true;
			SwingUtilities.invokeLater(() ->
			{
				if (session.button != null)
				{
					clientToolbar.removeNavigation(session.button);
				}
			});
		}
		clientThread.invokeLater(() ->
		{
			if (!active)
			{
				invalidatePending();
				tracker.clear();
			}
		});
		log.debug("BankedClues stopped!");
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged gameStateChanged)
	{
		switch (gameStateChanged.getGameState())
		{
			case LOGIN_SCREEN:
			case LOGGING_IN:
			case HOPPING:
			case CONNECTION_LOST:
				invalidatePending();
				tracker.suspend();
				publishCounts(null, false, false);
				break;
			default:
				break;
		}
		if (gameStateChanged.getGameState() == GameState.LOGGED_IN)
		{
			queueRefresh();
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		clientThread.invokeLater(() ->
		{
			if (active)
			{
				invalidatePending();
				tracker.suspend();
				publishCounts(null, false, false);
				queueRefresh();
			}
		});
	}

	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{
		clientThread.invokeLater(() ->
		{
			if (active)
			{
				invalidatePending();
				tracker.clear();
				publishCounts(null, false, false);
				queueRefresh();
			}
		});
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN)
		{
			queueRefresh();
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN)
		{
			queueRefresh();
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.BANK)
		{
			if (isBankOpen())
			{
				bankUpdatePending = true;
			}
			else
			{
				bankChangedAway = true;
			}
			queueRefresh();
		}
		else if (event.getContainerId() == InventoryID.INV)
		{
			queueRefresh();
		}
	}

	private void queueRefresh()
	{
		if (!active || refreshQueued)
		{
			return;
		}

		refreshQueued = true;
		int queuedGeneration = generation;
		UiSession session = uiSession;
		// Bank widgets and contents can arrive in either order. Read once both have settled.
		clientThread.invokeAtTickEnd(() ->
		{
			if (!active || session != uiSession || queuedGeneration != generation)
			{
				return;
			}
			refreshQueued = false;
			boolean bankUpdated = bankUpdatePending;
			boolean changedAway = bankChangedAway;
			bankUpdatePending = false;
			bankChangedAway = false;
			refreshBank(bankUpdated, changedAway);
		});
	}

	private boolean isBankOpen()
	{
		Widget bank = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
		return client.getGameState() == GameState.LOGGED_IN && bank != null && !bank.isHidden();
	}

	private void refreshBank(boolean bankUpdated, boolean changedAway)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			publishCounts(null, false, false);
			return;
		}

		tracker.selectProfile(configManager.getRSProfileKey());
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		Map<Integer, Long> relevant = ClueCounter.relevantItems(inventory == null ? null : inventory.getItems(), this::identifyClue);
		boolean bankOpen = isBankOpen();
		// A bank event observed while open is still authoritative if the bank closed later in this tick.
		if (bankOpen || bankUpdated)
		{
			ItemContainer container = client.getItemContainer(InventoryID.BANK);
			ClueCounts updated = ClueCounter.count(container == null ? null : container.getItems(), this::identifyClue)
				.orElse(null);
			if (updated != null)
			{
				tracker.refreshBank(updated, relevant);
				log.debug("Bank counts refreshed: {} scrolls, {} caskets", updated.getScrollTotal(), updated.getTotal(ClueItemType.CASKET));
			}
			else
			{
				tracker.markStale();
			}
		}
		else
		{
			tracker.observeInventory(relevant);
			if (changedAway)
			{
				tracker.markStale();
			}
		}
		publishCounts(tracker.getCounts(), tracker.isStale(), bankOpen);
	}

	private ClueItem identifyClue(int itemId)
	{
		ClueItem known = ClueItemClassifier.knownItem(itemId);
		if (known != null)
		{
			return known;
		}
		ItemComposition item = client.getItemDefinition(itemId);
		return item == null ? null : ClueItemClassifier.identify(itemId, item.getMembersName(), item.getPlaceholderTemplateId() != -1);
	}

	private void invalidatePending()
	{
		generation++;
		refreshQueued = false;
		bankUpdatePending = false;
		bankChangedAway = false;
	}

	private void publishCounts(ClueCounts snapshot, boolean stale, boolean bankOpen)
	{
		UiSession session = uiSession;
		if (session != null)
		{
			SwingUtilities.invokeLater(() ->
			{
				if (!session.stopped && session.panel != null)
				{
					if (!session.rendered || !Objects.equals(snapshot, session.lastCounts)
						|| stale != session.lastStale || bankOpen != session.lastBankOpen)
					{
						session.panel.showCounts(snapshot, stale, bankOpen);
						session.lastCounts = snapshot;
						session.lastStale = stale;
						session.lastBankOpen = bankOpen;
						session.rendered = true;
					}
				}
			});
		}
	}

	private static BufferedImage createIcon()
	{
		BufferedImage image = new BufferedImage(20, 20, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		try
		{
			graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			graphics.setColor(new Color(220, 193, 138));
			graphics.fillRoundRect(4, 2, 12, 16, 3, 3);
			graphics.setColor(new Color(105, 76, 39));
			graphics.drawRoundRect(4, 2, 12, 16, 3, 3);
			graphics.drawLine(7, 6, 13, 6);
			graphics.drawLine(7, 9, 13, 9);
			graphics.drawLine(7, 12, 11, 12);
		}
		finally
		{
			graphics.dispose();
		}
		return image;
	}

	private static final class UiSession
	{
		private volatile boolean stopped;
		// Accessed only on the Swing event dispatch thread.
		private BankedCluesPanel panel;
		private NavigationButton button;
		private boolean rendered;
		private ClueCounts lastCounts;
		private boolean lastStale;
		private boolean lastBankOpen;
	}
}

package com.bankedclues;

import java.util.HashMap;
import java.util.Map;
import java.util.Optional;
import java.util.function.IntFunction;
import net.runelite.api.Item;

final class ClueCounter
{
	private ClueCounter()
	{
	}

	/** An absent snapshot is different from an available bank containing no clues. */
	static Optional<ClueCounts> count(Item[] items, IntFunction<ClueItem> identify)
	{
		if (items == null)
		{
			return Optional.empty();
		}

		long[][] quantities = new long[ClueItemType.values().length][ClueTier.values().length];
		for (Item item : items)
		{
			if (item == null || item.getId() < 0 || item.getQuantity() <= 0)
			{
				continue;
			}

			ClueItem clue = identify.apply(item.getId());
			if (clue != null)
			{
				quantities[clue.getType().ordinal()][clue.getTier().ordinal()] += item.getQuantity();
			}
		}
		return Optional.of(new ClueCounts(quantities));
	}

	/** Preserve item identity as well as quantity to notice clue-step changes. */
	static Map<Integer, Long> relevantItems(Item[] items, IntFunction<ClueItem> identify)
	{
		if (items == null)
		{
			return null;
		}
		Map<Integer, Long> relevant = new HashMap<>();
		for (Item item : items)
		{
			if (item != null && item.getId() >= 0 && item.getQuantity() > 0 && identify.apply(item.getId()) != null)
			{
				relevant.merge(item.getId(), (long) item.getQuantity(), Long::sum);
			}
		}
		return relevant;
	}
}

package com.bankedclues;

import java.util.Arrays;

/** Immutable counts for a bank snapshot that was available. */
final class ClueCounts
{
	private final long[][] quantities;

	ClueCounts(long[][] quantities)
	{
		this.quantities = new long[quantities.length][];
		for (int i = 0; i < quantities.length; i++)
		{
			this.quantities[i] = quantities[i].clone();
		}
	}

	long get(ClueTier tier, ClueItemType type)
	{
		return quantities[type.ordinal()][tier.ordinal()];
	}

	long getTotal(ClueItemType type)
	{
		return Arrays.stream(quantities[type.ordinal()]).sum();
	}

	long getScrollTotal()
	{
		return getScrollTotal(null);
	}

	long getTotal(ClueItemType type, ClueTier tier)
	{
		return tier == null ? getTotal(type) : get(tier, type);
	}

	long getScrollTotal(ClueTier tier)
	{
		long total = 0;
		for (ClueItemType type : ClueItemType.values())
		{
			if (type != ClueItemType.CASKET)
			{
				total += getTotal(type, tier);
			}
		}
		return total;
	}

	@Override
	public boolean equals(Object other)
	{
		return other instanceof ClueCounts && Arrays.deepEquals(quantities, ((ClueCounts) other).quantities);
	}

	@Override
	public int hashCode()
	{
		return Arrays.deepHashCode(quantities);
	}
}

package com.bankedclues;

final class ClueItem
{
	private final ClueTier tier;
	private final ClueItemType type;

	ClueItem(ClueTier tier, ClueItemType type)
	{
		this.tier = tier;
		this.type = type;
	}

	ClueTier getTier()
	{
		return tier;
	}

	ClueItemType getType()
	{
		return type;
	}
}

package com.bankedclues;

import java.util.HashMap;
import java.util.Map;
import net.runelite.api.gameval.ItemID;

final class ClueItemClassifier
{
	private static final Map<Integer, ClueItem> ITEMS = new HashMap<>();

	static
	{
		// IDs are ordered Beginner through Master; natural sources have no Master variant.
		register(ClueItemType.GEODE, ItemID.MINING_CLUE_GEODE_BEGINNER, ItemID.MINING_CLUE_GEODE_EASY,
			ItemID.MINING_CLUE_GEODE_MEDIUM, ItemID.MINING_CLUE_GEODE_HARD, ItemID.MINING_CLUE_GEODE_ELITE);
		register(ClueItemType.BOTTLE, ItemID.FISHING_CLUE_BOTTLE_BEGINNER, ItemID.FISHING_CLUE_BOTTLE_EASY,
			ItemID.FISHING_CLUE_BOTTLE_MEDIUM, ItemID.FISHING_CLUE_BOTTLE_HARD, ItemID.FISHING_CLUE_BOTTLE_ELITE);
		register(ClueItemType.NEST, ItemID.WC_CLUE_NEST_BEGINNER, ItemID.WC_CLUE_NEST_EASY,
			ItemID.WC_CLUE_NEST_MEDIUM, ItemID.WC_CLUE_NEST_HARD, ItemID.WC_CLUE_NEST_ELITE);
		register(ClueItemType.BOX, ItemID.LEAGUE_CLUE_BOX_BEGINNER, ItemID.LEAGUE_CLUE_BOX_EASY,
			ItemID.LEAGUE_CLUE_BOX_MEDIUM, ItemID.LEAGUE_CLUE_BOX_HARD, ItemID.LEAGUE_CLUE_BOX_ELITE,
			ItemID.LEAGUE_CLUE_BOX_MASTER);
		register(ClueItemType.CASKET, ItemID.TRAIL_REWARD_CASKET_BEGINNER, ItemID.TRAIL_REWARD_CASKET_EASY,
			ItemID.TRAIL_REWARD_CASKET_MEDIUM, ItemID.TRAIL_REWARD_CASKET_HARD, ItemID.TRAIL_REWARD_CASKET_ELITE,
			ItemID.TRAIL_REWARD_CASKET_MASTER);
	}

	private ClueItemClassifier()
	{
	}

	private static void register(ClueItemType type, int... itemIds)
	{
		ClueTier[] tiers = ClueTier.values();
		for (int i = 0; i < itemIds.length; i++)
		{
			ITEMS.put(itemIds[i], new ClueItem(tiers[i], type));
		}
	}

	static ClueItem knownItem(int itemId)
	{
		// Only actual item IDs are registered, never noted or placeholder IDs.
		return ITEMS.get(itemId);
	}

	static int spriteItemId(ClueItemType type, ClueTier filter)
	{
		// The All view uses representative Hard-tier sprites for combined counts.
		ClueTier tier = filter == null ? ClueTier.HARD : filter;
		if (type == ClueItemType.SCROLL)
		{
			switch (tier)
			{
				case BEGINNER:
					return ItemID.TRAIL_CLUE_BEGINNER;
				case EASY:
					return ItemID.TRAIL_CLUE_EASY_SIMPLE001;
				case MEDIUM:
					return ItemID.TRAIL_CLUE_MEDIUM_EMOTE001;
				case HARD:
					return ItemID.TRAIL_CLUE_HARD_MAP001;
				case ELITE:
					return ItemID.TRAIL_CLUE_ELITE_MUSIC001;
				case MASTER:
					return ItemID.TRAIL_CLUE_MASTER;
				default:
					return -1;
			}
		}
		for (Map.Entry<Integer, ClueItem> entry : ITEMS.entrySet())
		{
			ClueItem item = entry.getValue();
			if (item.getType() == type && item.getTier() == tier)
			{
				return entry.getKey();
			}
		}
		return -1;
	}

	static ClueItem identify(int itemId, String name, boolean placeholder)
	{
		if (placeholder)
		{
			return null;
		}
		ClueItem known = knownItem(itemId);
		if (known != null)
		{
			return known;
		}
		ClueTier tier = ClueTier.identify(name, false);
		return tier == null ? null : new ClueItem(tier, ClueItemType.SCROLL);
	}
}

package com.bankedclues;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.BorderFactory;
import javax.swing.Icon;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.QuantityFormatter;

/** A bank-style item slot with a sprite, stack quantity and category caption. */
final class ClueItemTile extends JPanel
{
	private final ClueItemType type;
	private final ItemManager itemManager;
	private final JLabel sprite = new JLabel("", SwingConstants.CENTER);
	private final JLabel caption;
	private int spriteId = Integer.MIN_VALUE;
	private String quantity = "\u2014";

	ClueItemTile(ClueItemType type, ItemManager itemManager)
	{
		this.type = type;
		this.itemManager = itemManager;
		setLayout(new BorderLayout(0, 3));
		setOpaque(false);
		setBorder(BorderFactory.createEmptyBorder(30, 6, 7, 6));
		setPreferredSize(new Dimension(98, 112));
		caption = new JLabel(type.getDisplayName(), SwingConstants.CENTER);
		caption.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		add(sprite, BorderLayout.CENTER);
		add(caption, BorderLayout.SOUTH);
	}

	void showCount(ClueTier tier, Long count)
	{
		int itemId = ClueItemClassifier.spriteItemId(type, tier);
		if (itemId != spriteId)
		{
			spriteId = itemId;
			sprite.setIcon(null);
			sprite.setText(itemId < 0 ? "N/A" : "");
			if (itemId >= 0)
			{
				AsyncBufferedImage image = itemManager.getImage(itemId);
				if (image != null)
				{
					// Keep RuneLite's asynchronous repaint listener when enlarging its sprite.
					image.addTo(sprite);
					sprite.setIcon(new ScaledIcon(sprite.getIcon()));
				}
			}
		}
		quantity = count == null || itemId < 0 ? "\u2014" : QuantityFormatter.quantityToStackSize(count);
		String scope = tier == null ? "All tiers" : tier.getDisplayName();
		String tooltip = scope + " - " + type.getDisplayName() + ": "
			+ (itemId < 0 ? "not available for this tier" : count == null ? "visit a bank to load counts" : count.toString());
		setToolTipText(tooltip);
		sprite.setToolTipText(tooltip);
		caption.setToolTipText(tooltip);
		getAccessibleContext().setAccessibleName(tooltip);
		repaint();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		super.paintComponent(graphics);
		Graphics2D g = (Graphics2D) graphics.create();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setColor(ColorScheme.DARKER_GRAY_COLOR);
			g.fillRoundRect(0, 0, getWidth() - 1, getHeight() - 1, 8, 8);
			g.setColor(new Color(80, 76, 65));
			g.drawRoundRect(0, 0, getWidth() - 1, getHeight() - 1, 8, 8);
		}
		finally
		{
			g.dispose();
		}
	}

	@Override
	protected void paintChildren(Graphics graphics)
	{
		super.paintChildren(graphics);
		Graphics g = graphics.create();
		try
		{
			g.setFont(getFont().deriveFont(Font.BOLD, 24f));
			g.setColor(Color.BLACK);
			g.drawString(quantity, 9, 27);
			g.setColor(spriteId < 0 ? ColorScheme.LIGHT_GRAY_COLOR : Color.YELLOW);
			g.drawString(quantity, 8, 26);
		}
		finally
		{
			g.dispose();
		}
	}

	private static final class ScaledIcon implements Icon
	{
		private static final float SCALE = 1.75f;
		private final Icon original;

		private ScaledIcon(Icon original)
		{
			this.original = original;
		}

		@Override
		public void paintIcon(Component component, Graphics graphics, int x, int y)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			try
			{
				g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
				g.translate(x, y);
				g.scale(SCALE, SCALE);
				original.paintIcon(component, g, 0, 0);
			}
			finally
			{
				g.dispose();
			}
		}

		@Override
		public int getIconWidth()
		{
			return Math.round(original.getIconWidth() * SCALE);
		}

		@Override
		public int getIconHeight()
		{
			return Math.round(original.getIconHeight() * SCALE);
		}
	}
}

