	@Test
	public void firstInventoryObservationDoesNotInventBankData()
	{
		tracker.observeInventory(Map.of(ItemID.LEAGUE_CLUE_BOX_EASY, 1L));
		assertNull(tracker.getCounts());
		assertFalse(tracker.isStale());
	}

